import queue, threading

events: queue.Queue[Event] = queue.Queue(maxsize=256)

def drain() -> None:
    while True:
        try:
            ev = events.get_nowait()     # get() blocks until one arrives
        except queue.Empty:
            return
        handle(ev)

threading.Thread(target=drain, daemon=True).start()
events.put(Event('sound', 'bloop', 0.8))  # returns immediately
